// ─── Normaliza o payload recebido da Evolution API ───────────────────────
// Evolution envia diferentes formatos dependendo do tipo de mensagem.
// Ajuste os caminhos abaixo se o seu webhook usar um envelope diferente.

const body = $input.first().json;
const data = body.data || body;
const message = data.message || {};
const key = data.key || {};

// chat_id: número do contato (formato: 5511999999999@s.whatsapp.net)
const chatId = key.remoteJid || data.remoteJid || '';
const fromMe  = key.fromMe === true || data.fromMe === true;

// Timestamp da mensagem em epoch (segundos). Fallback = agora.
const ts = Number(data.messageTimestamp) || Math.floor(Date.now() / 1000);

// Extrair texto puro de todos os tipos de mensagem relevantes
let text = '';
if (message.conversation) {
  text = message.conversation;
} else if (message.extendedTextMessage?.text) {
  text = message.extendedTextMessage.text;
} else if (message.imageMessage?.caption) {
  text = `[imagem] ${message.imageMessage.caption}`;
} else if (message.audioMessage) {
  // Se você tiver um nó de transcrição, coloque o resultado aqui.
  // Por ora, use um placeholder.
  text = '[áudio — insira transcrição aqui]';
} else if (message.documentMessage) {
  text = `[documento: ${message.documentMessage.fileName || 'sem nome'}]`;
} else {
  text = '[mensagem não suportada]';
}

if (!chatId || !text) {
  // Encerra a execução silenciosamente para mensagens inválidas
  return [];
}

return [{
  json: {
    provider : 'whatsapp-evolution',
    chat_id  : chatId,
    from_me  : fromMe,
    text     : text,
    ts       : ts
  }
}];

// ─── Centraliza a geração de todas as chaves Redis ──────────────────────
// PARAMETRIZÁVEL: altere ENV abaixo para 'dev', 'staging' ou 'prod'
const ENV = 'prod';

const chatId = $json.chat_id;
const myTs   = $json.ts; // timestamp desta mensagem (epoch segundos)

// PARAMETRIZÁVEL: TTL da janela de debounce em segundos (60–300 s)
const DEBOUNCE_TTL_SEC = 120;

return [{
  json: {
    ...$json,
    env                : ENV,
    debounce_ttl_sec   : DEBOUNCE_TTL_SEC,
    debounce_key       : `wa:${ENV}:user:${chatId}`,
    buffer_key         : `wa:${ENV}:user:${chatId}:buffer`,
    last_ts_key        : `wa:${ENV}:user:${chatId}:last_ts`,
    lock_key           : `wa:${ENV}:user:${chatId}:lock`,
    myTs               : myTs
  }
}];

// Após o Wait, $json contém somente o resultado do GET do Redis.
// Recuperamos os metadados originais do nó 'Define Redis Keys'.
const original = $('Define Redis Keys').first().json;
const redisLastTs = Number($json.value || 0);

return [{
  json: {
    ...original,
    redis_last_ts: redisLastTs
  }
}];

// O nó LRANGE do Redis pode retornar:
//  a) Um único item com value = array de strings
//  b) Múltiplos items (um por elemento da lista)
// Normalizamos ambos os casos abaixo.

const original = $('Check Winner').first().json;

// Coleta todos os items retornados pelo LRANGE
const allItems = $input.all();
let rawList = [];

if (allItems.length === 1 && Array.isArray(allItems[0].json.value)) {
  // Caso (a): valor já é array
  rawList = allItems[0].json.value;
} else {
  // Caso (b): cada item é um elemento da lista
  rawList = allItems.map(i => i.json.value || i.json);
}

const messages = rawList
  .filter(Boolean)
  .map(item => {
    try {
      return typeof item === 'string' ? JSON.parse(item) : item;
    } catch {
      return { role: 'user', text: String(item), ts: 0 };
    }
  })
  .sort((a, b) => a.ts - b.ts); // garante ordem cronológica

return [{
  json: {
    chat_id       : original.chat_id,
    provider      : original.provider,
    myTs          : original.myTs,
    messages_batch: messages
  }
}];
